-- Kano health sector 2026 monthly expenditure tracking (Jan-Jun).
--
-- Source: "2026 MDAs BUDGET TRACKING TEMPLATE-8.xlsx" (IBP monthly tracking
-- workbook, one sheet per MDA; supersedes TEMPLATE-7). Line-level monthly
-- actuals for overhead and capital, plus HMB/PHCMB personnel. A row with
-- amount 0 is an explicit zero submission; absence of a row means nothing was
-- submitted for that month.
--
-- Requires migration 20260727090000_monthly_expenditure_tracking.sql and seeds
-- 001 (reference data) + 010 (budget lines).
--
-- Idempotent: upserts on the natural key
-- (fiscal_year, mda_id, budget_class, economic_code, source_row_number, month).

begin;

do $$
begin
  if to_regclass('public.monthly_expenditure_tracking') is null then
    raise exception 'Missing table monthly_expenditure_tracking -- apply migration 20260727090000.';
  end if;
end $$;

create temporary table _mt_load(
  mda_code text, cls text, econ text, descr text, row_no int, month smallint, amount numeric(18,2)
) on commit drop;


   approved_budget_line_id, month, amount, source_label, source_row_number)
select 2026, m.id, v.cls, v.econ, nullif(v.descr,''), bl.id, v.month, v.amount,
       '2026 MDAs BUDGET TRACKING TEMPLATE-8', v.row_no
from _mt_load v
join public.mdas m on m.code = v.mda_code
left join lateral (
  select l.id from public.approved_budget_lines l
  where l.fiscal_year = 2026 and l.mda_id = m.id
    and l.budget_class = v.cls and l.economic_code = v.econ
  order by
    -- capital: prefer the line whose project description matches; recurrent
    -- lines are unique per economic code so the tie-break is moot.
    (md5(lower(regexp_replace(btrim(coalesce(l.project_description,'')), '\s+', ' ', 'g')))
       = md5(lower(regexp_replace(btrim(v.descr), '\s+', ' ', 'g')))) desc,
    l.approved_amount desc
  limit 1
) bl on true
on conflict (fiscal_year, mda_id, budget_class, economic_code, coalesce(source_row_number, -1), month)
do update set amount = excluded.amount,
              description = excluded.description,
              approved_budget_line_id = excluded.approved_budget_line_id,
              source_label = excluded.source_label,
              updated_at = now();

commit;
